import java.io.*;
import java.util.*;

public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = reader.readLine().split(" ");
        int n = Integer.parseInt(tokens[0]);
        int budget = Integer.parseInt(tokens[1]);
        int[] nums = new int[n];
        int[] cum = new int[n];
        tokens = reader.readLine().split(" ");
        int bal = 0;
        for (int i = 0; i < n; i++) {
            nums[i] = Integer.parseInt(tokens[i]);
            if (nums[i] % 2 == 0) bal++;
            else bal--;
            cum[i] = bal;
        }
        ArrayList<Integer> cutCosts = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if (cum[i] == 0) {
                cutCosts.add(Math.abs(nums[i] - nums[i+1]));
            }
        }
        Collections.sort(cutCosts);
        int cuts = 0;
        int spent = 0;
        int i = 0;
        while (i < cutCosts.size() && spent + cutCosts.get(i) <= budget) {
            spent += cutCosts.get(i);
            cuts++;
            i++;
        }
        System.out.print(cuts);
    }
}
